def canon_cycle(c):
    c = list(c)
    rots = [tuple(c[i:]+c[:i]) for i in range(len(c))]
    return min(rots)  # lexicographically smallest rotation

# dedupe by canonical form
raw = {(6,), (9,5,2,1,4), (5,2,1,4,9), (4,9,5,2,1), (1,4,9,5,2), (2,1,4,9,5)}
